def split(s): return [x.strip() for x in s.split('|') if x.strip()]
def group(name, fields, note=None):
    d={'grupo':name,'campos':split(fields)}
    if note:d['observacao']=note
    return d
def tab(ident,title,groups,attachments='',notes=()):
    return {'id':ident,'titulo':title,'origem':'Interface SISCAT observada em leitura, em processo deferido de Fabricação / AUTOMOVEL / PASSAGEIRO / M1 / elétrico com fonte externa','grupos':groups,'anexos_ou_comprovacoes':split(attachments),'notas':list(notes),'validacao_de_obrigatoriedade_dos_campos':'Não testada por submissão. Regras de outros perfis e de edição não foram exercitadas.'}

