    rows=observed['niveis'][f'nivel{level}']
    assert len(rows)==len(updates)
    for n,(row,u) in enumerate(zip(rows,updates),1):
        refs,article,meaning,applicability,assessment,partlist=u
        tip=next(x['ajuda'] for x in observed['ajudas'] if x['item']==row['item'])
        matrix.append({'id':f'ENS-{level}-{n:02}','rotulo_siscat':row['item'],'nivel_observado':level,'ajuda_original':tip,'significado':meaning,'fontes':srcids(refs),'dispositivo':article,'aplicabilidade':{'estado':'a_enquadrar','condicao':applicability},'revisao':{'estado':'pendencia' if assessment.startswith('PENDENTE') else 'vinculo_revisado_no_recorte','conclusao':assessment},'partes_3d':split(partlist),'entrega':{'secao':'DOS-07','tipo':'Relatório nível '+str(level)+' quando aplicável','observacao':'O rótulo e o nível da tela foram preservados; isso não decide sozinho a obrigação técnica.'},'detalhe_visitado':True,'campos_detalhe':next(x['campos'] for x in observed['detalhes'] if x['item']==row['item'])})

