# Entrega portátil: relatório, dados, PDFs/DOCs oficiais e manifesto. Textos extraídos de fontes não são consolidações legais.
zip_path=ROOT/'outputs'/'levantamento-seguranca-siscat.zip'
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted(OUT.iterdir()):
        if p.is_file():z.write(p,p.name)
    for e in man:
        if e.get('state')=='downloaded':
            ext='.doc' if e['id'].endswith('-doc') else '.pdf';p=SOURCES/(e['id']+ext)
            z.write(p,'fontes/'+p.name)
    z.write(capturefile,'siscat-capturas.json')
print(json.dumps({'guias':len(tabs),'ensaios':len(matrix),'complementares':len(extras),'pendencias':len(gaps),'fontes_adquiridas':sum(x.get('state')=='downloaded' for x in man),'zip_bytes':zip_path.stat().st_size,'seguranca_integral_fechada':False},ensure_ascii=False))
